template:
PREFIX schema: <https://schema.org/>
PREFIX seeds: <https://seeds.local/ontology/>
PREFIX q: <https://scbrown.github.io/quechua/ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?item ?id ?title ?closed ?revision ?reason WHERE {
 GRAPH <https://seeds.local/project/aegis> {
  { SELECT ?item ?closed WHERE {
    ?item schema:endTime ?closed .
    FILTER(?closed >= xsd:dateTime('{start}') && ?closed < xsd:dateTime('{end}'))
  } }
  ?item a schema:Action ; seeds:status "closed" ; schema:identifier ?id ; schema:name ?title ; schema:version ?revision .
  FILTER NOT EXISTS { ?item schema:keywords "inbox" }
  FILTER(!REGEX(STR(?title), '^[[:space:]]*(inbox:|mail:)', 'i'))
  OPTIONAL { ?item q:closeReason ?rawReason . BIND(SUBSTR(STR(?rawReason), 1, 240) AS ?reason) }
 }
} ORDER BY DESC(?closed) ?id LIMIT 20
